let placeIndex: Map<string, Place> | null = null

/** 장소 id → [위도, 경도]. PLACES에 없으면 undefined */
export function placeGeo(id?: string): [number, number] | undefined {
  if (!id) return undefined
  if (!placeIndex) placeIndex = new Map(Object.values(PLACES).flat().map((p) => [p.id, p]))
  const p = placeIndex.get(id)
  return p ? [p.lat, p.lng] : undefined
}

